from psycopg import Connection
from psycopg.types.json import Jsonb
from pydantic import JsonValue

INSERT_STATE = """-- Create the first revision; a concurrent insert becomes a version conflict.
INSERT INTO recipeweave.user_state (subject, revision, payload, updated_at)
VALUES (%(subject)s, 1, %(payload)s, CURRENT_TIMESTAMP);
"""
UPDATE_STATE = """-- Replace only the expected revision and return the new revision.
UPDATE recipeweave.user_state SET revision = revision + 1, payload = %(payload)s,
updated_at = CURRENT_TIMESTAMP WHERE subject = %(subject)s AND revision = %(revision)s
RETURNING revision;
"""


def insert_state(
    connection: Connection[tuple[object, ...]], subject: str, payload: dict[str, JsonValue]
) -> None:
    connection.execute(INSERT_STATE, {"subject": subject, "payload": Jsonb(payload)})


def update_state(
    connection: Connection[tuple[object, ...]],
    subject: str,
    revision: int,
    payload: dict[str, JsonValue],
) -> bool:
    cursor = connection.execute(
        UPDATE_STATE, {"subject": subject, "revision": revision, "payload": Jsonb(payload)}
    )
    return cursor.rowcount == 1
